package main

import (
	"fmt"
	"syscall"
)

func main() {
	fds, err := syscall.Socketpair(syscall.AF_UNIX, syscall.SOCK_STREAM, 0)
	if err != nil {
		fmt.Println("创建 socketpair 失败:", err)
		return
	}
	defer syscall.Close(fds[0])
	defer syscall.Close(fds[1])

	// 接收端设成非阻塞，否则 read 会一直阻塞
	if err := syscall.SetNonblock(fds[0], true); err != nil {
		fmt.Println("设置非阻塞失败:", err)
		return
	}

	if _, err := syscall.Write(fds[1], []byte("hello")); err != nil {
		fmt.Println("写失败:", err)
		return
	}

	// ET 模式必须一直读到 EAGAIN 为止
	buf := make([]byte, 4)
	total := 0
	for {
		n, err := syscall.Read(fds[0], buf)
		if err == syscall.EAGAIN {
			break
		}
		if err != nil {
			fmt.Println("读失败:", err)
			return
		}
		total += n
	}
	fmt.Println("累计读到", total, "字节")
}

package main

import (
	"fmt"
	"net"
	"syscall"
)

func main() {
	ln, err := net.Listen("tcp", "127.0.0.1:0")
	if err != nil {
		fmt.Println("监听失败:", err)
		return
	}
	defer ln.Close()

	go func() {
		c, err := ln.Accept()
		if err != nil {
			return
		}
		defer c.Close()
		c.Write([]byte("hello"))
	}()

	conn, err := net.Dial("tcp", ln.Addr().String())
	if err != nil {
		fmt.Println("连接失败:", err)
		return
	}
	defer conn.Close()

	// 通过 SyscallConn 拿到底层 fd，再把它设成非阻塞
	raw, err := conn.(*net.TCPConn).SyscallConn()
	if err != nil {
		fmt.Println("获取底层 fd 失败:", err)
		return
	}
	var setErr error
	if err := raw.Control(func(fd uintptr) {
		setErr = syscall.SetNonblock(int(fd), true)
	}); err != nil || setErr != nil {
		fmt.Println("设置非阻塞失败:", err, setErr)
		return
	}
	fmt.Println("已把连接的 fd 设成 O_NONBLOCK")
}
